(function(){
'use strict';
const $=id=>document.getElementById(id),M=window.CrisisModel;
const slides=[...document.querySelectorAll('.slide')];
const titles=['The crisis','Social trends and sharing','Pre-drop demand','The last hoodie','Staff operations','Implementation','References'];
let index=0,phase=0,first='Aarav',model=M.create(),sequence=0,flightTimer=null,receiptDeadline=null;
const set=(id,value)=>{$(id).textContent=value;};
const flash=id=>{$(id).classList.remove('changed');void $(id).offsetWidth;$(id).classList.add('changed');};
const dots=slides.map((s,i)=>{const b=document.createElement('button');b.textContent=i+1;b.setAttribute('aria-label',`Slide ${i+1}: ${titles[i]}`);b.addEventListener('click',()=>go(i));$('slide-dots').append(b);return b;});
function hold(){return model.holds.find(x=>x.id==='DR-001');}
function resetInventory(){const interests=model.interests;model=M.create();model.interests=interests;phase=0;clearTimeout(flightTimer);flightTimer=null;clearReminder();renderRace();renderDashboard();}
function commitRace(){const second=first==='Aarav'?'Meera':'Aarav';M.reserve(model,first,'hoodie','L',1,'DR-001',0);M.reserve(model,second,'hoodie','L',1,'DR-002',0);M.enqueue(model,second,'hoodie','L');receiptDeadline=Date.now()+86400000;phase=3;renderRace();renderDashboard();}
function renderSocial(analyze=false){
 const text=$('social-input').value,products=[{sku:'HD-001',aliases:['Oversized Hoodie','#OversizedHoodie','HD-001']}];
 const matched=window.DropSimulation.matchProduct(text,products).length>0;
 set('social-match',analyze?(matched?'Matched: HD-001 / Oversized hoodie':'No product matched. Try #OversizedHoodie.'):'Post → keyword → product code');
 set('social-trend',analyze?(matched?'TRENDING DROP / 10 mentions vs usual 2 (sample)':'No trending label without a product match.'):'Compare mentions with the usual level.');
 $('social-meter').style.width=analyze&&matched?'100%':'20%';
}
function renderBadge(){const name=$('badge-name').value.trim()||'Your name',collected=$('badge-state').value==='collected';set('badge-person',`${name.toUpperCase()} / HOODIE / L`);$('badge-heading').innerHTML=collected?'PICKED<br>IT UP.':'GOT MY<br>HOLD.';}
function renderReceipt(){const shown=phase===3;$('race-receipt').hidden=!shown;if(!shown)return;const current=hold();if(current?.status==='expired'){set('race-receipt',`RECEIPT DR-001 / ${first} / EXPIRED / invalid for pickup`);return;}if(current?.status==='sold'){set('race-receipt',`RECEIPT DR-001 / ${first} / COLLECTED`);return;}const seconds=Math.max(0,Math.ceil(((receiptDeadline||Date.now()+86400000)-Date.now())/1000));const clock=[Math.floor(seconds/3600),Math.floor(seconds%3600/60),seconds%60].map(x=>String(x).padStart(2,'0')).join(':');set('race-receipt',`RECEIPT DR-001 / ${first} / ${clock} left to collect`);}
function renderDemand(){const totals=M.demand(model),max=Math.max(4,...Object.values(totals));const container=$('demand-bars');
for(const [k,label] of [['hoodie:M','Hoodie / M'],['hoodie:L','Hoodie / L'],['hoodie:XL','Hoodie / XL'],['tee:M','Tee / M'],['tee:L','Tee / L'],['tee:XL','Tee / XL']]){
 let row=container.querySelector(`[data-variant="${k}"]`);if(!totals[k]&&!row)continue;
 if(!row){row=document.createElement('div');row.className=`bar-row${k.startsWith('tee')?' tee':''}`;row.dataset.variant=k;const labelEl=document.createElement('span');labelEl.textContent=label;const track=document.createElement('div');track.className='bar-track';const fill=document.createElement('div');fill.className='bar-fill';track.append(fill);const count=document.createElement('b');row.append(labelEl,track,count);container.append(row);}
 row.querySelector('.bar-fill').style.width=`${(totals[k]||0)/max*100}%`;row.querySelector('b').textContent=totals[k]||0;
}
set('interest-total',Object.values(totals).reduce((a,b)=>a+b,0));renderDashboard();}
function renderRace(){const second=first==='Aarav'?'Meera':'Aarav';document.querySelector('.race-board').classList.toggle('arriving',phase===1);
for(const [name,suffix]of[['Aarav','a'],['Meera','m']]){const winner=name===first;set(`status-${suffix}`,phase===0?'Ready to reserve':phase===1?'Request in flight':phase===2?'At the same stock record':winner?'Hold confirmed / 24h':'No stock / stays waitlisted');$(`person-${suffix}`).classList.toggle('winner',phase===3&&winner);$(`person-${suffix}`).classList.toggle('waiting',phase===3&&!winner);}
set('race-stock',phase===3?0:1);set('lock-label',phase<2?'Waiting for requests':phase===2?'Check stock + save hold together':'Saved / 1 active hold');renderReceipt();
set('race-caption',phase===0?'Click below. Both requests travel to the same size L stock record.':phase===1?'Both arrive at the same time. They ask for the same size L hoodie.':phase===2?'The database handles these stock changes one at a time. Each request checks the stock again.':`${first} gets the hold. ${second} sees zero available and remains on the waitlist. Only one hoodie is held.`);
set('race-action',['Send both requests →','Requests travelling…','Confirm one hold →','Replay simultaneous requests ↺'][phase]);$('race-action').disabled=phase===1;$('race-swap').disabled=phase===1;set('race-swap',`Try ${first==='Aarav'?'Meera':'Aarav'} first`);}
function clearReminder(){$('reminder-text').value='';$('reminder-text').readOnly=true;$('copy-reminder').disabled=true;set('reminder-feedback','Staff review and send through their usual channel.');}
function renderDashboard(){const h=hold(),stats=M.metrics(model),totals=M.demand(model);set('conversion',`${stats.conversion}%`);set('conversion-detail',`${stats.converted} of ${stats.customers} customers`);set('uncollected',stats.uncollected);const ranked=['M','L','XL'].map(size=>[size,totals[`hoodie:${size}`]||0]);const top=Math.max(...ranked.map(x=>x[1]));set('top-size',ranked.filter(x=>x[1]===top).map(x=>x[0]).join('/'));set('top-size-detail',`${top} units requested${ranked.filter(x=>x[1]===top).length>1?' each':''}`);
const held=h?.status==='held',sold=h?.status==='sold',expired=h?.status==='expired';$('stock-token').style.transform=`translateX(${held?100:sold?200:0}%)`;for(const [id,count]of[['available',model.stock['hoodie:L']],['held',held?1:0],['sold',sold?1:0]]){$(`${id}-chip`).querySelector('b').textContent=count;$(`${id}-chip`).classList.toggle('selected',count>0);}
set('hold-customer',`${h?.customer||first} / Hoodie / L`);set('hold-avatar',(h?.customer||first)[0]);set('hold-badge',h?h.status.toUpperCase():'AVAILABLE');set('hold-deadline',held?'2 hours left to collect':sold?'Collected at the physical store':expired?'Deadline passed / stock returned':'Run the reservation demo to create a hold');set('clock-value',held?'02h':sold?'✓':'00h');$('expire-hold').disabled=!held;$('collect-hold').disabled=!held;$('generate-reminder').disabled=!held;
const next=model.queues['hoodie:L']?.[0];set('queue-notice',expired&&next?`${next} is next. Priority notice: the size L hoodie is ready to claim.`:sold?'Pickup complete. No stock is offered to the queue.':`Next in line: ${next||'Meera'}. Notify after the current hold expires.`);
set('operation-status',held?'Demo time: 22 hours after booking. Remind the customer, then collect or expire the hold.':sold?'Collected: held becomes sold. Available stock stays at zero.':expired?'The hold expired. The hoodie is available again. Running the release job twice still adds only one unit.':'Open this slide to create a sample hold.');}
function updateNotes(){const n=window.PRESENTER_NOTES[index];set('notes-title',`${index+1}. ${n.title}`);set('notes-duration',`${n.duration} seconds / Hinglish narration`);const box=$('notes-content');box.replaceChildren();for(const [text,cls]of[[n.cue,'cue'],...n.paragraphs.map(x=>[x,'']),[n.research,'research-note']]){const p=document.createElement('p');p.className=cls;p.textContent=text;box.append(p);}}
function go(i){index=Math.max(0,Math.min(6,i));if(index===4&&!hold())commitRace();slides.forEach((s,j)=>{s.hidden=j!==index;dots[j].toggleAttribute('aria-current',j===index);if(j===index)dots[j].setAttribute('aria-current','step');});$('previous').disabled=index===0;$('next').disabled=index===6;set('next',index===6?'End of presentation':'Next slide →');updateNotes();document.title=`${index+1}/7 · ${titles[index]} / The Dressing Room`;try{history.replaceState(null,'',`#slide-${index+1}`);}catch(_){}set('announcement',`Slide ${index+1}: ${titles[index]}`);}
$('interest-form').addEventListener('submit',e=>{e.preventDefault();if(!$('interest-form').reportValidity())return;const quantity=Number($('interest-qty').value),item=$('interest-item').value,size=$('interest-size').value;sequence++;const ok=M.interest(model,{id:`sample-${sequence}`,customer:`Sample customer ${sequence}`,item,size,quantity});if(!ok.ok){set('interest-result','Enter a whole quantity from 1 to 10.');return;}renderDemand();set('interest-result',`Added ${quantity} ${item==='hoodie'?'hoodie':'tee'} ${quantity===1?'unit':'units'} / size ${size}. Demand updated. Stock unchanged.`);flash('interest-total');});
$('analyze-social').addEventListener('click',()=>{renderSocial(true);flash('social-match');});$('badge-name').addEventListener('input',renderBadge);$('badge-state').addEventListener('change',renderBadge);
$('race-action').addEventListener('click',()=>{if(phase===3){resetInventory();return;}if(phase===2){commitRace();flash('race-stock');return;}if(phase!==0)return;phase=1;renderRace();const reduced=window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;flightTimer=setTimeout(()=>{phase=2;renderRace();flightTimer=null;},reduced?0:1050);});
$('race-swap').addEventListener('click',()=>{first=first==='Aarav'?'Meera':'Aarav';resetInventory();});
$('expire-hold').addEventListener('click',()=>{M.expire(model,'DR-001',86400);M.expire(model,'DR-001',86401);clearReminder();renderDashboard();flash('available-chip');});
$('collect-hold').addEventListener('click',()=>{M.collect(model,'DR-001',23*3600);clearReminder();renderDashboard();flash('sold-chip');});
$('reset-hold').addEventListener('click',()=>{resetInventory();commitRace();});
$('generate-reminder').addEventListener('click',()=>{const event=M.remind(model,'DR-001',22*3600);if(!event)return;$('reminder-text').value=event.text;$('reminder-text').readOnly=false;$('copy-reminder').disabled=false;set('reminder-feedback','2-hour job prepared for SMS / Push. Staff can also edit and copy this draft.');flash('reminder-text');});
$('copy-reminder').addEventListener('click',async()=>{try{await navigator.clipboard.writeText($('reminder-text').value);set('reminder-feedback','Copied. Staff can send the reviewed text.');}catch(_){$('reminder-text').focus();$('reminder-text').select();set('reminder-feedback','Text selected. Press Ctrl+C or use your device’s Copy action.');}});
const techText=["React + TypeScript builds the storefront, staff console and separate benchmark dashboard. The Go API serves the built frontend and local assets.", "Go net/http validates JSON, staff keys and idempotency keys. Each stock mutation saves its response and event with the inventory transaction.", "PostgreSQL + pgxpool records physical scan units, locations and holds. A transaction lock serializes stock changes and online allocation leaves two available units.", "The separate Go worker uses Asynq for scheduled work and retries, plus a recovery sweep. It rechecks state before reminders, expiry release and FIFO offers.", "Redis + Lua counts customer requests through go-redis. Redis also stores the Asynq job queue. PostgreSQL continues to enforce stock rules during Redis failure.", "The Go load generator sends real loopback HTTP requests with bounded goroutines. The dashboard streams observed metrics over SSE and exports saved JSON/CSV results."];
document.querySelectorAll('[data-tech]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-tech]').forEach(x=>x.classList.toggle('active',x===b));set('tech-caption',techText[Number(b.dataset.tech)]);}));
function notes(open){$('notes').hidden=!open;$('notes-toggle').setAttribute('aria-pressed',String(open));(open?$('notes-close'):$('notes-toggle')).focus();}
$('notes-toggle').addEventListener('click',()=>notes($('notes').hidden));$('notes-close').addEventListener('click',()=>notes(false));
$('download-badge').addEventListener('click',()=>{const c=document.createElement('canvas');c.width=1080;c.height=1920;const ctx=c.getContext('2d');if(!ctx)return;ctx.fillStyle='#c7f36b';ctx.fillRect(0,0,1080,1920);ctx.fillStyle='#1a2412';ctx.font='bold 38px Arial';ctx.fillText('THE DRESSING ROOM',80,140);ctx.font='bold 130px Arial';const collected=$('badge-state').value==='collected';ctx.fillText(collected?'PICKED':'GOT MY',80,650);ctx.fillText(collected?'IT UP.':'HOLD.',80,800);ctx.font='36px Arial';ctx.fillText(`${($('badge-name').value.trim()||'Your name').slice(0,24)} / HOODIE / L`,80,1090);ctx.fillText(collected?'Collected at The Dressing Room.':'24 hours to collect at the store.',80,1170);ctx.font='26px Arial';ctx.fillText('ILLUSTRATIVE SAMPLE / NOT A VALID RECEIPT',80,1770);c.toBlob(blob=>{if(!blob)return;const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='dressing-room-sample-badge.png';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);},'image/png');});
$('next').addEventListener('click',()=>go(index+1));$('previous').addEventListener('click',()=>go(index-1));$('replay').addEventListener('click',()=>{if(index===1){$('social-input').value='I want the #OversizedHoodie for the next drop!';$('badge-name').value='Aarav';$('badge-state').value='reserved';renderSocial();renderBadge();}if(index===2){model=M.create();sequence=0;phase=0;clearTimeout(flightTimer);$('demand-bars').replaceChildren();clearReminder();renderDemand();renderRace();set('interest-result','Aarav and Meera already want the size L hoodie.');}if(index===3)resetInventory();if(index===4){resetInventory();commitRace();}if(index===5)document.querySelector('[data-tech="0"]').click();});
$('print').addEventListener('click',()=>window.print());$('fullscreen').addEventListener('click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch(_){set('announcement','Fullscreen is unavailable in this browser.');}});
document.addEventListener('keydown',e=>{if(/INPUT|SELECT|TEXTAREA/.test(e.target.tagName)||e.target.isContentEditable||e.ctrlKey||e.metaKey||e.altKey)return;const k=e.key.toLowerCase();if(k==='escape'&&!$('notes').hidden){notes(false);return;}if(!$('notes').hidden&&['arrowright','arrowleft',' '].includes(k))return;if(k==='arrowright'||k==='pagedown'||(k===' '&&!e.target.closest('button,a'))){e.preventDefault();go(index+1);}if(k==='arrowleft'||k==='pageup'){e.preventDefault();go(index-1);}if(/^[1-7]$/.test(k))go(Number(k)-1);if(k==='n')notes($('notes').hidden);if(k==='f')$('fullscreen').click();if(k==='r')$('replay').click();if(k==='home')go(0);if(k==='end')go(6);});
window.addEventListener('hashchange',()=>{const m=location.hash.match(/^#slide-([1-7])$/);if(m)go(Number(m[1])-1);});
let printBackup;
window.addEventListener('beforeprint',()=>{clearTimeout(flightTimer);if(phase===1)phase=2;printBackup={model:structuredClone(model),phase,first,receiptDeadline,reminder:$('reminder-text').value};model=M.create();first='Aarav';commitRace();M.expire(model,'DR-001',86400);renderDashboard();renderDemand();$('reminder-text').value='Example reminder before expiry: Hi Aarav, your size L hoodie is ready for pickup. Please collect within 2 hours at The Dressing Room.';set('operation-status','Acceptance demo: one hold succeeds. At expiry, the hoodie becomes available again.');});
window.addEventListener('afterprint',()=>{if(!printBackup)return;model=printBackup.model;phase=printBackup.phase;first=printBackup.first;receiptDeadline=printBackup.receiptDeadline;renderRace();renderDashboard();renderDemand();$('reminder-text').value=printBackup.reminder;printBackup=null;});
renderSocial();renderBadge();renderDemand();renderRace();setInterval(renderReceipt,1000);const hash=location.hash.match(/^#slide-([1-7])$/);go(hash?Number(hash[1])-1:0);
})();
